local ActionUtil = require "amf.middleware.ui.util.ActionUtil"
local WaterfallDyPaymentView = class("WaterfallDyPaymentView", Node)

local FRAME_TIME = 0.033
function WaterfallDyPaymentView:create(goodsId, offerInfo)
    local view = WaterfallDyPaymentView.new(CCNode:create())
    view:init(goodsId, offerInfo)
    return view
end

function WaterfallDyPaymentView:init(goodsId, offerInfo)
    self.goodsObject = GoodsManager:getGoods(goodsId)
    self.offerInfo = offerInfo

    self:initBaseView()
    self:initByGoods()
end

function WaterfallDyPaymentView:initBaseView()
    local uiData = force_require("amf.feature.localactivity.waterfallgift.view.uisource.WaterfallDouyinPayNode_UI")
    local ui = UIBuilder:buildUI(uiData, self, "dyPayNode")
    self:addChild(ui)
end

function WaterfallDyPaymentView:initByGoods()
    self.dyPayBtn:setContent({ text = "" })
    self.originPriceLabel:setString("￥"..self.goodsObject:getPrice())

    if self.offerInfo.finalPrice then
        self.realPriceLabel:setString("￥"..tostring(self.offerInfo.finalPrice))
    else
        self.realPriceLabel:setString("随机立减")
    end


    local originMarkLabelWidth = self.dyMarkLabel:getContentSize().width
    self.dyMarkLabel:setString(tostring(self.offerInfo.operationTip))
    local extendWidth = self.dyMarkLabel:getContentSize().width - originMarkLabelWidth
    LayoutUtil:move(self.markNode, -extendWidth / 2, 0)

    local targetMarkBgWidth = self.markBg:getPreferredSize().width + extendWidth
    self.markBg:setPreferredWidth(targetMarkBgWidth)
    self.markBg.targetMarkBgWidth = targetMarkBgWidth
end

function WaterfallDyPaymentView:appearWithSimpleAni(isFirst)
    if isFirst then
        local oScale = self.dyPayBtn:getScale()
        self.dyPayBtn:runAction(CCRepeatForever:create(ActionUtil:sequence({
            CCScaleTo:create(FRAME_TIME * 15, 1.1 * oScale, 1.1 * oScale),
            CCScaleTo:create(FRAME_TIME * 15, oScale, oScale),
        })))
    end

    self.realPriceLabel:setScale(0.5)
    self.realPriceLabel:runAction(ActionUtil:sequence({
        CCDelayTime:create(FRAME_TIME * 2),
        CCScaleTo:create(FRAME_TIME * 3, 0.9791, 0.9791),
    }))

    self.originPriceLabel:runAction(CCSpawn:createWithTwoActions(
            CCScaleTo:create(FRAME_TIME * 5, 0.628, 0.628),
            CCMoveBy:create(FRAME_TIME * 5, ccp(0, -18.5))
    ))
end

function WaterfallDyPaymentView:runMarkNodeAppearAction(hitCallback)
    self.dyIcon:setVisible(false)
    self.dyIcon:setScale(10)
    self.dyIcon:runAction(ActionUtil:sequence({
        CCDelayTime:create(FRAME_TIME * 12),
        CCCallFunc:create(function()
            self.dyIcon:setVisible(true)
        end),
        CCEaseSineIn:create(CCScaleTo:create(FRAME_TIME * 4, 3.486, 3.486)),
        CCEaseSineOut:create(CCScaleTo:create(FRAME_TIME * 5, 0.8, 0.8)),
        CCEaseSineInOut:create(CCScaleTo:create(FRAME_TIME * 3, 1.05, 1.05)),
        CCEaseSineInOut:create(CCScaleTo:create(FRAME_TIME * 3, 1.0, 1.0))
    }))

    self.dyMarkLabel:setOpacity(0)
    self.dyMarkLabel:runAction(ActionUtil:sequence({
        CCDelayTime:create(FRAME_TIME * 24),
        CCFadeIn:create(FRAME_TIME * 7)
    }))

    self.markBg:setVisible(false)
    local curWidth = 41
    self.markBg:setPreferredWidth(curWidth)

    self.markBg:runAction(ActionUtil:sequence({
        CCDelayTime:create(FRAME_TIME * 18),
        CCCallFunc:create(function()
            self.markBg:setVisible(true)
            if hitCallback then
                hitCallback()
            end

            local actionWidth = self.markBg.targetMarkBgWidth - curWidth
            local runTime = FRAME_TIME * 10 * 1000
            local EaseCurve = require "amf.script.math.EaseCurve"
            local t = TimeKit:timeInMillis()

            local alarmId
            alarmId = TimerUtil.addAlarm(function()
                if self.markBg.isDisposed then return end
                local dt = TimeKit:timeInMillis() - t
                local p = EaseCurve:quarticOut(math.min(dt / runTime, 1))

                curWidth = math.min(curWidth + actionWidth * p, self.markBg.targetMarkBgWidth)
                self.markBg:setPreferredWidth(curWidth)
                if dt > runTime then
                    TimerUtil.removeAlarm(alarmId)
                end
            end, 0.0167, 0)
        end)
    }))
end

function WaterfallDyPaymentView:runBtnAppearAction(isFirst)
    local btnSpine = UICreateUtil:createSpine("amf/waterfallgift/spine/douyinzhifu.skel")
    self:addChild(btnSpine)
    btnSpine:setPositionXY(103, 146)
    btnSpine:playOnceAndDispose("in")

    self.redLine:setScaleX(0)
    self.redLine:runAction(ActionUtil:sequence({
        CCDelayTime:create(FRAME_TIME * 41),
        CCScaleTo:create(FRAME_TIME * 5, 1, 1)
    }))

    self.originPriceLabel:runAction(ActionUtil:sequence({
        CCDelayTime:create(FRAME_TIME * 41),
        CCEaseSineInOut:create(CCScaleTo:create(FRAME_TIME * 5, 1.5, 1.5)),
        CCDelayTime:create(17 * FRAME_TIME),
        CCSpawn:createWithTwoActions(
                CCEaseSineOut:create(CCScaleTo:create(FRAME_TIME * 5, 0.628, 0.628)),
                CCMoveBy:create(FRAME_TIME * 5, ccp(0, -18.5))
        )
    }))

    self.realPriceLabel:setVisible(false)
    self.realPriceLabel:setScale(0.5)
    local actScale = self.offerInfo.finalPrice and 1.65 or 1.3
    self.realPriceLabel:runAction(ActionUtil:sequence({
        CCDelayTime:create(FRAME_TIME * 65),
        CCCallFunc:create(function()
            self.realPriceLabel:setVisible(true)
        end),
        CCEaseSineInOut:create(CCScaleTo:create(FRAME_TIME * 5, actScale, actScale)),
        CCDelayTime:create(19 * FRAME_TIME),
        CCEaseSineInOut:create(CCScaleTo:create(FRAME_TIME * 3, 0.7492, 0.7492)),
        CCEaseSineInOut:create(CCScaleTo:create(FRAME_TIME * 3, 0.9791, 0.9791))
    }))

    local oScale = self.dyPayBtn:getScale()
    self.dyPayBtn:runAction(ActionUtil:sequence({
        CCDelayTime:create(FRAME_TIME * 66),
        CCEaseSineInOut:create(CCScaleTo:create(FRAME_TIME * 5, 1.1 * oScale, 1.1 * oScale)),
        CCDelayTime:create(20 * FRAME_TIME),
        CCEaseSineOut:create(CCScaleTo:create(FRAME_TIME * 3, 0.8 * oScale, 0.8 * oScale)),
        CCEaseSineInOut:create(CCScaleTo:create(FRAME_TIME * 3, 1.05 * oScale, 1.05 * oScale)),
        CCEaseSineInOut:create(CCScaleTo:create(FRAME_TIME * 3, 1.1 * oScale, 1.1 * oScale)),
        CCEaseSineInOut:create(CCScaleTo:create(FRAME_TIME * 15, oScale, oScale)),
        CCCallFunc:create(function()
            if isFirst then
                self:runBtnBreathAction()
            end
        end)
    }))
end

function WaterfallDyPaymentView:runBtnBreathAction()
    local oScale = 1
    self.dyPayBtn:stopAllActions()
    self.dyPayBtn:runAction(CCRepeatForever:create(ActionUtil:sequence({
        CCEaseSineInOut:create(CCScaleTo:create(FRAME_TIME * 15, 1.1 * oScale, 1.1 * oScale)),
        CCEaseSineInOut:create(CCScaleTo:create(FRAME_TIME * 15, oScale, oScale)),
    })))
end

function WaterfallDyPaymentView:runParentHitAction(node)
    if not node or node.isDisposed then return end
    node:runAction(ActionUtil:sequence({
        CCEaseSineInOut:create(CCScaleTo:create(FRAME_TIME * 1, 0.98, 0.98)),
        CCEaseSineOut:create(CCScaleTo:create(FRAME_TIME * 2, 1.02, 1.02)),
        CCEaseSineInOut:create(CCScaleTo:create(FRAME_TIME * 3, 1, 1)),
    }))
end

function WaterfallDyPaymentView:setBuyBtnCallback(callback)
    self.dyPayBtn:setOnTouchTapedCallback(callback)
end

return WaterfallDyPaymentView